import re

with open('sympy/functions/special/zeta_functions.py', 'r') as f:
    content = f.read()

# Fix 1: Change the _eval_expand_func for s=1
# Replace: -log(1 + exp_polar(-I*pi)*z) 
# With:    -log(1 - z)
old = "    def _eval_expand_func(self, **hints):\n        from sympy import log, expand_mul, Dummy, exp_polar, I\n        s, z = self.args\n        if s == 1:\n            return -log(1 + exp_polar(-I*pi)*z)"
new = "    def _eval_expand_func(self, **hints):\n        from sympy import log, expand_mul, Dummy, exp_polar, I\n        s, z = self.args\n        if s == 1:\n            return -log(1 - z)"
content = content.replace(old, new)

# Fix 2: Add evaluation of polylog(2, 1/2) in eval method
# We need to add a special case for s=2, z=1/2
old_eval = """    @classmethod
    def eval(cls, s, z):
        if z == 1:
            return zeta(s)
        elif z == -1:
            return -dirichlet_eta(s)
        elif z == 0:
            return 0"""

new_eval = """    @classmethod
    def eval(cls, s, z):
        if z == 1:
            return zeta(s)
        elif z == -1:
            return -dirichlet_eta(s)
        elif z == 0:
            return 0

        if s.is_integer and s.is_positive:
            from sympy import Rational, GoldenRatio
            if z == S.Half:
                if s == 1:
                    return -log(2)
                elif s == 2:
                    return pi**2/12 - log(2)**2/2
            elif z == 2:
                if s == 1:
                    return -I*pi + log(2)
            elif z == Rational(-1, 2):
                if s == 1:
                    return log(Rational(2, 3))
                elif s == 2:
                    return -pi**2/12 + log(2)**2/2"""

content = content.replace(old_eval, new_eval)

# Also fix the docstring example
old_doc = "    >>> expand_func(polylog(1, z))\n    -log(z*exp_polar(-I*pi) + 1)"
new_doc = "    >>> expand_func(polylog(1, z))\n    -log(1 - z)"
content = content.replace(old_doc, new_doc)

with open('sympy/functions/special/zeta_functions.py', 'w') as f:
    f.write(content)

print("Done")
EOF
